BEGIN;
DROP SCHEMA IF EXISTS bird_formula1 CASCADE;
CREATE SCHEMA bird_formula1;
CREATE TABLE bird_formula1.constructorresults ("constructorresultsid" bigint NOT NULL, "raceid" bigint NOT NULL, "constructorid" bigint NOT NULL, "points" double precision, "status" text, PRIMARY KEY ("constructorresultsid"));
\copy bird_formula1.constructorresults FROM '/data/constructorresults.csv' WITH (FORMAT csv, HEADER true, NULL '\N');
DO $$ BEGIN IF (SELECT count(*) FROM bird_formula1.constructorresults) <> 11082 THEN RAISE EXCEPTION 'fixture count mismatch: constructorresults'; END IF; END $$;
CREATE TABLE bird_formula1.constructorstandings ("constructorstandingsid" bigint NOT NULL, "raceid" bigint NOT NULL, "constructorid" bigint NOT NULL, "points" double precision NOT NULL, "position" bigint, "positiontext" text, "wins" bigint NOT NULL, PRIMARY KEY ("constructorstandingsid"));
\copy bird_formula1.constructorstandings FROM '/data/constructorstandings.csv' WITH (FORMAT csv, HEADER true, NULL '\N');
DO $$ BEGIN IF (SELECT count(*) FROM bird_formula1.constructorstandings) <> 11836 THEN RAISE EXCEPTION 'fixture count mismatch: constructorstandings'; END IF; END $$;
CREATE TABLE bird_formula1.driverstandings ("driverstandingsid" bigint NOT NULL, "raceid" bigint NOT NULL, "driverid" bigint NOT NULL, "points" double precision NOT NULL, "position" bigint, "positiontext" text, "wins" bigint NOT NULL, PRIMARY KEY ("driverstandingsid"));
\copy bird_formula1.driverstandings FROM '/data/driverstandings.csv' WITH (FORMAT csv, HEADER true, NULL '\N');
DO $$ BEGIN IF (SELECT count(*) FROM bird_formula1.driverstandings) <> 31578 THEN RAISE EXCEPTION 'fixture count mismatch: driverstandings'; END IF; END $$;
CREATE TABLE bird_formula1.laptimes ("raceid" bigint NOT NULL, "driverid" bigint NOT NULL, "lap" bigint NOT NULL, "position" bigint, "time" text, "milliseconds" bigint, PRIMARY KEY ("raceid","driverid","lap"));
\copy bird_formula1.laptimes FROM '/data/laptimes.csv' WITH (FORMAT csv, HEADER true, NULL '\N');
DO $$ BEGIN IF (SELECT count(*) FROM bird_formula1.laptimes) <> 400524 THEN RAISE EXCEPTION 'fixture count mismatch: laptimes'; END IF; END $$;
CREATE TABLE bird_formula1.pitstops ("raceid" bigint NOT NULL, "driverid" bigint NOT NULL, "stop" bigint NOT NULL, "lap" bigint NOT NULL, "time" text NOT NULL, "duration" text, "milliseconds" bigint, PRIMARY KEY ("raceid","driverid","stop"));
\copy bird_formula1.pitstops FROM '/data/pitstops.csv' WITH (FORMAT csv, HEADER true, NULL '\N');
DO $$ BEGIN IF (SELECT count(*) FROM bird_formula1.pitstops) <> 5815 THEN RAISE EXCEPTION 'fixture count mismatch: pitstops'; END IF; END $$;
CREATE TABLE bird_formula1.qualifying ("qualifyid" bigint NOT NULL, "raceid" bigint NOT NULL, "driverid" bigint NOT NULL, "constructorid" bigint NOT NULL, "number" bigint NOT NULL, "position" bigint, "q1" text, "q2" text, "q3" text, PRIMARY KEY ("qualifyid"));
\copy bird_formula1.qualifying FROM '/data/qualifying.csv' WITH (FORMAT csv, HEADER true, NULL '\N');
DO $$ BEGIN IF (SELECT count(*) FROM bird_formula1.qualifying) <> 6967 THEN RAISE EXCEPTION 'fixture count mismatch: qualifying'; END IF; END $$;
CREATE TABLE bird_formula1.races ("raceid" bigint NOT NULL, "year" bigint NOT NULL, "round" bigint NOT NULL, "circuitid" bigint NOT NULL, "name" text NOT NULL, "date" date NOT NULL, "time" text, "url" text, PRIMARY KEY ("raceid"));
\copy bird_formula1.races FROM '/data/races.csv' WITH (FORMAT csv, HEADER true, NULL '\N');
DO $$ BEGIN IF (SELECT count(*) FROM bird_formula1.races) <> 954 THEN RAISE EXCEPTION 'fixture count mismatch: races'; END IF; END $$;
CREATE TABLE bird_formula1.results ("resultid" bigint NOT NULL, "raceid" bigint NOT NULL, "driverid" bigint NOT NULL, "constructorid" bigint NOT NULL, "number" bigint, "grid" bigint NOT NULL, "position" bigint, "positiontext" text NOT NULL, "positionorder" bigint NOT NULL, "points" double precision NOT NULL, "laps" bigint NOT NULL, "time" text, "milliseconds" bigint, "fastestlap" bigint, "rank" bigint, "fastestlaptime" text, "fastestlapspeed" text, "statusid" bigint NOT NULL, PRIMARY KEY ("resultid"));
\copy bird_formula1.results FROM '/data/results.csv' WITH (FORMAT csv, HEADER true, NULL '\N');
DO $$ BEGIN IF (SELECT count(*) FROM bird_formula1.results) <> 23179 THEN RAISE EXCEPTION 'fixture count mismatch: results'; END IF; END $$;
COMMIT;
